insert into questions (subject, topic, statement, option_a, option_b, option_c, option_d, correct, feedback) values
('fisica', 'Camp Gravitatori i Lleis de Kepler', 'Segons la segona llei de Kepler, què li succeeix a la velocitat orbital d''un planeta quan s''apropa al periastre?', 'Augmenta per tal de conservar el moment angular.', 'Disminueix a causa de l''atracció gravitatòria.', 'Es manté constant al llarg de tota l''òrbita.', 'S''anul·la momentàniament abans de canviar de direcció.', 'A', 'Correcte. Per conservar el moment angular ($L = m \cdot v \cdot r$), si el radi disminueix, la velocitat ha d''augmentar.'),
('fisica', 'Camp Gravitatori i Lleis de Kepler', 'Si la distància entre dos planetes es redueix a la meitat, la força d''atracció gravitatòria entre ells:', 'Es redueix a la meitat.', 'Es duplica.', 'Es quadruplica.', 'Es manté constant.', 'C', 'Segons la llei de Newton ($F \propto 1/r^2$), si $r$ es divideix per 2, la força es multiplica per $2^2 = 4$.'),
('fisica', 'Camp Gravitatori i Lleis de Kepler', 'L''energia mecànica d''un satèl·lit en òrbita circular és:', 'Igual a la seva energia cinètica.', 'Negativa i igual a la meitat de la seva energia potencial.', 'Zero.', 'Positiva i igual al doble de l''energia cinètica.', 'B', 'En una òrbita circular, $E_c = -E_p/2$, de manera que $E_m = E_c + E_p = E_p/2$.'),
('fisica', 'Camp Gravitatori i Lleis de Kepler', 'La velocitat d''escapament d''un coet des de la Terra depèn de:', 'La massa del coet.', 'L''angle de llançament.', 'La massa i el radi de la Terra exclusivament.', 'L''energia cinètica inicial únicament.', 'C', 'S''obté igualant $E_m = 0$, resultant en $v = \sqrt{2GM/R}$, on no intervé la massa del coet.'),
('fisica', 'Camp Gravitatori i Lleis de Kepler', 'El treball fet pel camp gravitatori terrestre per moure un satèl·lit en una òrbita circular val:', 'Zero.', 'Depèn de la massa del satèl·lit.', 'És positiu perquè la força és atractiva.', 'Igual a l''energia cinètica.', 'A', 'El potencial és constant en una òrbita circular ($\Delta V = 0$), per tant $W = -m\Delta V = 0$.'),
('fisica', 'Camp Gravitatori i Lleis de Kepler', 'El moment angular d''un planeta que orbita el Sol en una el·lipse:', 'És màxim al periastre.', 'És mínim a l''apoastre.', 'És rigorosament constant.', 'Depèn de l''energia mecànica.', 'C', 'Com que la força gravitatòria és central, el moment de les forces és zero i el moment angular es conserva.'),
('fisica', 'Camp Gravitatori i Lleis de Kepler', 'Segons la 3a Llei de Kepler, si el radi orbital es quadruplica, el període orbital:', 'Es multiplica per 2.', 'Es multiplica per 4.', 'Es multiplica per 8.', 'Es divideix per 2.', 'C', 'Com que $T^2 \propto r^3$, si $r$ és $4$ vegades major, $r^3 = 64$, i per tant $T = \sqrt{64} = 8$.'),
('fisica', 'Camp Gravitatori i Lleis de Kepler', 'El camp gravitatori a l''interior d''un planeta esfèric homogeni (a distància $r < R$):', 'És zero.', 'Disminueix proporcionalment al quadrat de $r$.', 'Creix linealment amb la distància $r$ des del centre.', 'És igual que a la superfície.', 'C', 'A l''interior d''una esfera homogènia, $g$ creix de manera directament proporcional a $r$ fins arribar a la superfície.'),
('fisica', 'Camp Gravitatori i Lleis de Kepler', 'Dues masses puntuals estan separades una distància $d$. El camp gravitatori total s''anul·la en un punt:', 'Més proper a la massa més petita.', 'Més proper a la massa més gran.', 'Exactament al mig.', 'Mai es pot anul·lar.', 'A', 'Per igualar els camps ($GM_1/r_1^2 = GM_2/r_2^2$), el punt ha d''estar més a prop de la massa menor per compensar.'),
('fisica', 'Camp Gravitatori i Lleis de Kepler', 'L''energia potencial gravitatòria de dues masses separades una distància finita:', 'Pot ser positiva si les masses són molt grans.', 'És sempre negativa.', 'És nul·la.', 'Depèn de si el moviment és d''atracció o repulsió.', 'B', 'Per conveni, és zero a l''infinit. Com que s''ha de fer treball per separar-les contra l''atracció, $E_p$ a distància finita sempre és negativa.'),
('fisica', 'Camp Elèctric', 'Les línies de camp elèctric creades per una càrrega negativa:', 'Són circumferències tancades.', 'Són radials i apunten cap a l''exterior.', 'Són radials i apunten cap a la càrrega.', 'No existeixen per càrregues negatives.', 'C', 'Les línies indiquen la trajectòria d''una càrrega de prova positiva, que seria atreta cap a la càrrega negativa.'),
('fisica', 'Camp Elèctric', 'Si apropem un electró a una càrrega negativa fixa, l''energia potencial del sistema:', 'Disminueix.', 'Augmenta.', 'Es manté constant.', 'S''anul·la.', 'B', 'Estem realitzant treball contra la força de repulsió elèctrica per apropar-los, augmentant l''energia emmagatzemada (potencial).'),
('fisica', 'Camp Elèctric', 'Dues càrregues positives diferents estan separades per una distància. El camp elèctric pot ser nul:', 'En cap punt de l''espai.', 'Fora del segment que les uneix.', 'Al segment que les uneix, més a prop de la càrrega petita.', 'Al segment que les uneix, més a prop de la càrrega gran.', 'C', 'Els vectors s''oposen entre les càrregues, i cal apropar-se a la menor perquè els mòduls s''igualin.'),
('fisica', 'Camp Elèctric', 'El treball fet pel camp elèctric per moure una càrrega per una superfície equipotencial és:', 'Igual a l''energia cinètica final.', 'Màxim.', 'Negatiu.', 'Zero.', 'D', 'Com que a la superfície equipotencial $\Delta V = 0$, el treball $W = -q\Delta V$ és necessàriament zero.'),
('fisica', 'Camp Elèctric', 'Quina és la unitat del camp elèctric en el Sistema Internacional?', 'Joules/Coulomb (J/C)', 'Newtons/Coulomb (N/C)', 'Volts (V)', 'Tesles (T)', 'B', 'Segons la definició $\vec{E} = \vec{F}/q$, la unitat és Newton partit per Coulomb. (També V/m).'),
('fisica', 'Camp Elèctric', 'Si s''introdueix un dielèctric de permitivitat relativa $\epsilon_r > 1$ entre dues càrregues, la força elèctrica:', 'Disminueix.', 'Augmenta.', 'Es manté igual.', 'S''inverteix el sentit.', 'A', 'La constant $k = 1/(4\pi\epsilon)$. Si la permitivitat del medi augmenta, la constant disminueix, i la força és menor.'),
('fisica', 'Camp Elèctric', 'Un protó i un electró es deixen lliures en un camp elèctric uniforme.', 'Tenen la mateixa acceleració.', 'El protó té més acceleració.', 'L''electró té molta més acceleració.', 'No s''acceleren.', 'C', 'Les forces són iguals en mòdul, però com que la massa de l''electró és molt més petita, la seva acceleració ($a=F/m$) és molt major.'),
('fisica', 'Camp Elèctric', 'El camp elèctric a l''interior d''un conductor en equilibri electrostàtic:', 'És constant i depèn de la càrrega exterior.', 'És zero.', 'És màxim.', 'Depèn de la densitat del material.', 'B', 'Si hi hagués camp a l''interior, les càrregues lliures es mourien. Com que està en equilibri, $\vec{E} = 0$.'),
('fisica', 'Camp Elèctric', 'Per calcular el potencial total en un punt creat per un sistema de càrregues:', 'Se sumen vectorialment els potencials.', 'Es multipliquen les càrregues.', 'Se sumen escalarment, respectant el signe de cada càrrega.', 'Es fa el producte vectorial.', 'C', 'El potencial elèctric és una magnitud escalar, per tant és una simple suma algebraica on el signe de $q$ és vital.'),
('fisica', 'Camp Elèctric', 'Si una càrrega positiva es mou a favor de les línies de camp elèctric:', 'Va cap a potencials més baixos.', 'Va cap a potencials més alts.', 'El potencial no canvia.', 'L''energia potencial augmenta.', 'A', 'El camp elèctric sempre apunta des de les zones d''alt potencial cap a les zones de baix potencial.'),
('fisica', 'Camp Magnètic i Inducció', 'Un electró entra paral·lel a les línies d''un camp magnètic uniforme. Quina trajectòria descriurà?', 'Circular.', 'Parabòlica.', 'Rectilínia.', 'Helicoidal.', 'C', 'La força de Lorentz és $\vec{F} = q(\vec{v} \times \vec{B})$. Si $\vec{v}$ i $\vec{B}$ són paral·lels, el producte vectorial és zero, i no hi ha força magnètica.'),
('fisica', 'Camp Magnètic i Inducció', 'Dos fils paral·lels transporten corrent en sentits oposats. Entre ells hi haurà:', 'Una força d''atracció.', 'Una força de repulsió.', 'Cap força.', 'Un parell de torsió.', 'B', 'Segons la llei de Biot-Savart i la regla de la mà dreta, fils amb corrents en sentits oposats es repel·leixen.'),
('fisica', 'Camp Magnètic i Inducció', 'Què estableix la llei de Lenz respecte a la inducció electromagnètica?', 'La fem depèn de l''àrea.', 'El corrent induït s''oposa a la causa que el produeix (variació del flux).', 'El flux és constant.', 'La fem és directament proporcional a la resistència.', 'B', 'Justifica el signe negatiu ($-$) de la llei de Faraday, indicant que el camp induït actua per compensar el canvi de flux magnètic.'),
('fisica', 'Camp Magnètic i Inducció', 'La unitat de flux magnètic en el SI és:', 'Tesla (T)', 'Gauss (G)', 'Weber (Wb)', 'Henry (H)', 'C', 'El flux ($\Phi = B \cdot S \cdot \cos\alpha$) es mesura en Webers, on $1 \text{ Wb} = 1 \text{ T} \cdot \text{m}^2$.'),
('fisica', 'Camp Magnètic i Inducció', 'Si el radi de la trajectòria circular d''una partícula en un camp magnètic es duplica sense canviar de camp, vol dir que la seva velocitat:', 'S''ha reduït a la meitat.', 'Es manté igual.', 'S''ha duplicat.', 'S''ha quadruplicat.', 'C', 'Igualant força centrípeta i de Lorentz s''obté $R = mv / qB$. El radi és directament proporcional a la velocitat.'),
('fisica', 'Camp Magnètic i Inducció', 'En un generador de corrent altern, la força electromotriu màxima s''assoleix quan:', 'El flux magnètic és màxim.', 'El flux magnètic és nul i la variació és màxima.', 'L''espira està aturada.', 'L''angle entre el camp i la normal és de $0^\circ$.', 'B', 'La fem és la derivada del flux ($\varepsilon = -d\Phi/dt$). Quan la funció flux passa per zero, el seu pendent (variació) és màxim.'),
('fisica', 'Camp Magnètic i Inducció', 'El camp magnètic en el centre d''una espira circular augmenta si:', 'Augmentem el seu radi.', 'Reduïm la intensitat de corrent.', 'Reduïm el seu radi.', 'Canviem el sentit del corrent.', 'C', 'La fórmula és $B = \mu_0 I / (2R)$. Al reduir el denominador (radi), el valor del camp augmenta.'),
('fisica', 'Camp Magnètic i Inducció', 'La força magnètica sobre una càrrega en moviment produeix un treball:', 'Màxim quan la trajectòria és circular.', 'Nul en qualsevol cas.', 'Igual a la variació d''energia cinètica.', 'Proporcional a la càrrega.', 'B', 'Com que la força magnètica de Lorentz sempre és perpendicular al vector velocitat, el seu treball és sempre zero ($W = \vec{F} \cdot d\vec{r} = 0$).'),
('fisica', 'Camp Magnètic i Inducció', 'Quina partícula no patirà cap desviació en travessar un camp magnètic?', 'Un electró ràpid.', 'Un protó.', 'Un neutró.', 'Un ió positiu.', 'C', 'La força de Lorentz ($F = qvB$) depèn directament de la càrrega elèctrica. Com que el neutró té $q=0$, no interactua amb el camp magnètic.'),
('fisica', 'Camp Magnètic i Inducció', 'Si introduïm ràpidament un imant dins d''una bobina, el corrent induït:', 'Generarà un camp magnètic que atraurà l''imant.', 'Generarà un camp magnètic que repel·lirà l''imant.', 'No generarà cap camp magnètic extra.', 'Destruirà el camp de l''imant.', 'B', 'Per la llei de Lenz, l''espira s''oposa a l''augment del flux, generant un pol magnètic igual per repel·lir la intrusió de l''imant i frenar el canvi.'),
('fisica', 'Ones i Òptica', 'En l''equació d''una ona harmònica $y(x,t) = A \sin(kx - \omega t)$, el signe negatiu de l''interior indica que:', 'L''amplitud disminueix.', 'L''ona es propaga cap a l''esquerra (sentit negatiu de les x).', 'L''ona es propaga cap a la dreta (sentit positiu de les x).', 'És una ona estacionària.', 'C', 'Per conveni, si els signes de $kx$ i $\omega t$ són oposats, l''ona es propaga en el sentit positiu de l''eix OX.'),
('fisica', 'Ones i Òptica', 'Si la freqüència d''una ona augmenta mantenint constant la seva velocitat de propagació, què li passa a la longitud d''ona?', 'Augmenta.', 'Disminueix.', 'Es manté igual.', 'S''anul·la.', 'B', 'La velocitat és $v = \lambda \cdot f$. Si $v$ és constant i la freqüència $f$ augmenta, la longitud d''ona $\lambda$ ha de disminuir proporcionalment.'),
('fisica', 'Ones i Òptica', 'Perquè hi hagi reflexió total d''un raig de llum, s''ha de complir que:', 'Passi a un medi amb índex de refracció menor i superi l''angle límit.', 'Passi a un medi amb índex de refracció major.', 'L''angle d''incidència sigui zero (normal a la superfície).', 'S''utilitzi exclusivament llum monocromàtica vermella.', 'A', 'Condició indispensable: anar d''un medi més dens òpticament a un de menys dens ($n_1 > n_2$) perquè el raig s''allunyi de la normal fins a no poder sortir.'),
('fisica', 'Ones i Òptica', 'Segons el criteri DIN per a lents primes, si un objecte es troba a l''esquerra de la lent, la seva posició $s$ és:', 'Positiva.', 'Negativa.', 'Zero.', 'Depèn de si la lent és convergent o divergent.', 'B', 'Segons les normes DIN, el pol del sistema òptic és l''origen de coordenades. Tot allò situat a l''esquerra (d''on prové la llum) té coordenada negativa.'),
('fisica', 'Ones i Òptica', 'Si una lent convergent forma una imatge virtual:', 'L''objecte està més enllà del doble de la distància focal.', 'La imatge està invertida.', 'L''objecte està entre el focus objecte i el centre òptic de la lent.', 'Això és impossible, només formen imatges reals.', 'C', 'És el principi de la lupa. Quan $|s| < f''$, la imatge que es forma és virtual, dreta i més gran.'),
('fisica', 'Ones i Òptica', 'El nivell d''intensitat sonora ($\beta$) de dos altaveus emetent el mateix so:', 'És el doble que el d''un sol altaveu.', 'Suma 3 decibels (dB) al nivell d''un sol altaveu.', 'Es manté igual si estem a la mateixa distància.', 'Es redueix pel fenomen d''interferència.', 'B', 'Com que l''escala dels decibels és logarítmica ($\beta = 10 \log(I/I_0)$), duplicar la intensitat física ($2I$) suposa sumar només $\approx 3 \text{ dB}$ matemàticament.'),
('fisica', 'Ones i Òptica', 'El color de la llum visible està determinat directament per la seva:', 'Amplitud.', 'Freqüència (o longitud d''ona).', 'Velocitat en el buit.', 'Intensitat lumínica.', 'B', 'Cada color de l''espectre visible correspon a un interval específic de longituds d''ona (i freqüències), sent el vermell les més llargues i el violeta les més curtes.'),
('fisica', 'Ones i Òptica', 'Una lent divergent:', 'Forma sempre imatges reals.', 'Té una distància focal imatge ($f''$) negativa segons el criteri DIN.', 'Augmenta la grandària de les imatges.', 'Concentra els raigs de llum en el focus imatge.', 'B', 'En les lents divergents, el focus imatge $F''$ es troba a l''esquerra de la lent, per tant la seva coordenada és negativa. Les imatges que forma sempre són virtuals, dretes i menors.'),
('fisica', 'Ones i Òptica', 'Quina és la relació entre la velocitat de propagació d''una ona, el nombre d''ona ($k$) i la freqüència angular ($\omega$)?', '$v = k / \omega$', '$v = \omega / k$', '$v = \omega \cdot k$', '$v = 1 / (\omega \cdot k)$', 'B', 'Sabent que $\omega = 2\pi/T$ i $k = 2\pi/\lambda$, el quocient $\omega/k$ dona $\lambda/T$, que és exactament la velocitat de propagació $v$.'),
('fisica', 'Ones i Òptica', 'Si ens apropem cap a una font de so que està aturada (Efecte Doppler):', 'Percebem una freqüència aparent major que la real.', 'Percebem una freqüència aparent menor.', 'La velocitat del so augmenta realment.', 'La longitud d''ona canvia.', 'A', 'Al moure''ns cap a la font, interceptem els fronts d''ona amb més rapidesa, la qual cosa incrementa la freqüència percebuda (un so més agut).'),
('fisica', 'Física Moderna', 'A l''efecte fotoelèctric, si augmentem la intensitat de la llum incident mantenint la freqüència:', 'Els electrons s''emeten amb més energia cinètica.', 'El treball d''extracció del material disminueix.', 'S''emeten més electrons, però amb la mateixa energia cinètica.', 'No s''emetrà cap electró.', 'C', 'La intensitat augmenta el nombre de fotons incidents (i per tant el nombre d''electrons arrencats), però l''energia individual de cada electró només depèn de la freqüència de la llum.'),
('fisica', 'Física Moderna', 'El treball d''extracció d''un metall correspon a:', 'L''energia cinètica màxima dels electrons emesos.', 'L''energia mínima necessària per arrencar un electró de la seva superfície.', 'La freqüència de la llum multiplicada per la velocitat de la llum.', 'La massa defectiva del nucli de l''àtom.', 'B', 'És l''energia que el fotó gasta per "alliberar" l''electró del metall ($W = h \cdot f_0$). La resta d''energia es transforma en energia cinètica.'),
('fisica', 'Física Moderna', 'En una desintegració alfa ($\alpha$), el nucli emissor:', 'Manté el seu nombre atòmic i màssic.', 'Redueix el seu nombre màssic en 4 i l''atòmic en 2.', 'Augmenta el seu nombre atòmic en 1.', 'Emet exclusivament radiació electromagnètica.', 'B', 'La partícula alfa és un nucli d''Heli-4 ($^4_2\text{He}$), format per dos protons i dos neutrons, per tant la massa (A) baixa 4 i el nombre atòmic (Z) baixa 2.'),
('fisica', 'Física Moderna', 'En una desintegració beta menys ($\beta^-$), dins del nucli:', 'Un protó es transforma en un neutró.', 'Un neutró es transforma en un protó, emetent un electró i un antineutrí.', 'Es captura un electró de l''escorça.', 'El nombre màssic disminueix en una unitat.', 'B', 'El nombre de nucleons (A) no canvia, però un neutró es converteix en protó, incrementant el nombre atòmic (Z) en 1.'),
('fisica', 'Física Moderna', 'L''energia d''enllaç d''un nucli atòmic prové de:', 'L''energia cinètica dels electrons orbitant.', 'L''efecte fotoelèctric.', 'El defecte de massa en la seva formació, segons la relació $E = \Delta m \cdot c^2$.', 'La desintegració alfa exclusivament.', 'C', 'La suma de les masses dels protons i neutrons separats és lleugerament superior a la massa del nucli sencer. Aquesta diferència de massa es converteix en energia d''enllaç.'),
('fisica', 'Física Moderna', 'El temps necessari perquè la meitat dels nuclis d''una mostra radioactiva es desintegrin es coneix com:', 'Vida mitjana ($\tau$).', 'Constant de desintegració ($\lambda$).', 'Període de semidesintegració o semivida ($T_{1/2}$).', 'Activitat radioactiva.', 'C', 'És el període ($T_{1/2} = \ln 2 / \lambda$) necessari per reduir a la meitat el nombre de nuclis inestables inicials.'),
('fisica', 'Física Moderna', 'Segons l''equació de Planck, l''energia d''un fotó és:', 'Directament proporcional a la seva longitud d''ona.', 'Directament proporcional a la seva freqüència.', 'Independent del color de la llum.', 'Proporcional al quadrat de la seva velocitat.', 'B', 'L''equació és $E = h \cdot f$. Si la freqüència és major (com en la llum ultraviolada front a l''infraroja), l''energia del fotó és major.'),
('fisica', 'Física Moderna', 'La dualitat ona-corpuscle de De Broglie afirma que:', 'Només la llum té comportament de partícula.', 'Qualsevol partícula material en moviment té una longitud d''ona associada.', 'Els electrons no poden difractar-se.', 'La massa es conserva en totes les reaccions nuclears.', 'B', 'La hipòtesi de De Broglie indica que $\lambda = h / (m \cdot v)$, associant una ona a qualsevol partícula amb quantitat de moviment.'),
('fisica', 'Física Moderna', 'El potencial de frenada en un experiment de l''efecte fotoelèctric serveix per mesurar experimentalment:', 'El treball d''extracció directament.', 'La intensitat de la llum.', 'L''energia cinètica màxima dels electrons emesos.', 'La constant de Planck.', 'C', 'S''aplica un voltatge invers just suficient per aturar els electrons més ràpids. L''energia elèctrica aplicada equival a l''energia cinètica màxima ($q_e \cdot V_0 = E_c$).'),
('fisica', 'Física Moderna', 'Què ocorre amb l''activitat d''una mostra radioactiva (mesurada en Becquerels) amb el pas del temps?', 'Disminueix exponencialment.', 'Disminueix linealment de manera constant.', 'Es manté constant fins que de cop cau a zero.', 'Augmenta si es canvia de recipient.', 'A', 'L''activitat ($A$) és proporcional al nombre de nuclis existents ($A = \lambda N$). Com que el nombre de nuclis decau de forma exponencial ($N = N_0 e^{-\lambda t}$), l''activitat també ho fa.'),
('matematiques-ii', 'Àlgebra Lineal (Matrius i Sistemes)', 'Una matriu quadrada $A$ té matriu inversa $A^{-1}$ si i només si:', 'El seu determinant és igual a zero ($|A| = 0$).', 'Tots els seus elements de la diagonal principal són diferents de zero.', 'El seu determinant és diferent de zero ($|A| \neq 0$).', 'És una matriu simètrica.', 'C', 'Condició fonamental. La fórmula de la matriu inversa és $A^{-1} = \frac{1}{|A|} \text{Adj}(A)^T$. Si el determinant fos zero, el quocient no existiria.'),
('matematiques-ii', 'Àlgebra Lineal (Matrius i Sistemes)', 'Si tenim l''equació matricial $A \cdot X = B$ i sabem que la matriu $A$ és invertible, quina és l''expressió correcta per aïllar la matriu $X$?', '$X = B \cdot A^{-1}$', '$X = A^{-1} \cdot B$', '$X = \frac{B}{A}$', 'L''ordre no importa, el producte de matrius és commutatiu.', 'B', 'El producte de matrius NO és commutatiu. Per eliminar la $A$ de l''esquerra de la $X$, hem de multiplicar per $A^{-1}$ per l''esquerra a tots dos costats: $A^{-1} \cdot A \cdot X = A^{-1} \cdot B$.'),
('matematiques-ii', 'Àlgebra Lineal (Matrius i Sistemes)', 'Segons el Teorema de Rouché-Frobenius, un sistema d''equacions lineals amb $n$ incògnites és un Sistema Compatible Determinat (SCD) quan:', '$\text{Rang}(A) < \text{Rang}(A^*) = n$', '$\text{Rang}(A) = \text{Rang}(A^*) < n$', '$\text{Rang}(A) \neq \text{Rang}(A^*)$', '$\text{Rang}(A) = \text{Rang}(A^*) = n$', 'D', 'Si els rangs de la matriu de coeficients ($A$) i l''ampliada ($A^*$) coincideixen, el sistema té solució. Si a més coincideix amb el nombre d''incògnites ($n$), la solució és única (SCD).'),
('matematiques-ii', 'Àlgebra Lineal (Matrius i Sistemes)', 'Quina de les següents igualtats respecte al producte i la transposició de matrius és sempre certa?', '$(A \cdot B)^T = A^T \cdot B^T$', '$(A \cdot B)^T = B^T \cdot A^T$', '$(A + B)^T = A^T \cdot B^T$', '$(A \cdot B)^{-1} = A^{-1} \cdot B^{-1}$', 'B', 'La transposada del producte de dues matrius és el producte de les seves transposades però en ordre invers. El mateix succeeix amb la inversa: $(A \cdot B)^{-1} = B^{-1} \cdot A^{-1}$.'),
('matematiques-ii', 'Àlgebra Lineal (Matrius i Sistemes)', 'Si multipliquem tots els elements d''una fila d''un determinant per un nombre real $k$, què li passa al valor del determinant?', 'Es manté igual.', 'Queda multiplicat per $k$.', 'Queda multiplicat per $k^2$.', 'Es torna zero.', 'B', 'Per les propietats dels determinants, si una línia (fila o columna) està multiplicada per un factor $k$, aquest factor pot sortir a fora multiplicant tot el determinant.'),
('matematiques-ii', 'Àlgebra Lineal (Matrius i Sistemes)', 'Un sistema d''equacions homogeni (tots els termes independents són zero) pot ser Incompatible?', 'Sí, si el determinant de la matriu principal és zero.', 'No, sempre té almenys la solució trivial (totes les incògnites igual a 0).', 'Sí, si hi ha més equacions que incògnites.', 'Depèn del Teorema de Cramer.', 'B', 'En un sistema homogeni, $\text{Rang}(A)$ sempre serà igual a $\text{Rang}(A^*)$ perquè afegir una columna de zeros no augmenta el rang. Per tant, sempre és compatible (SCD o SCI).'),
('matematiques-ii', 'Àlgebra Lineal (Matrius i Sistemes)', 'Si la matriu $A$ és d''ordre $3 \times 3$ i el seu determinant val 5, quant val el determinant de $2A$?', '10', '15', '40', '5', 'C', 'Si multipliquem tota una matriu d''ordre $n$ per $k$, el determinant queda multiplicat per $k^n$. En aquest cas: $|2A| = 2^3 \cdot |A| = 8 \cdot 5 = 40$.'),
('matematiques-ii', 'Àlgebra Lineal (Matrius i Sistemes)', 'Segons el Teorema de Rouché-Frobenius, què significa que $\text{Rang}(A) \neq \text{Rang}(A^*)$?', 'El sistema té infinites solucions.', 'El sistema té una única solució.', 'El sistema és Incompatible (no té solució).', 'Faltes dades per saber-ho.', 'C', 'Si la matriu ampliada té més rang que la de coeficients, significa que els termes independents introdueixen una contradicció lineal (ex: $0x + 0y + 0z = 5$).'),
('matematiques-ii', 'Àlgebra Lineal (Matrius i Sistemes)', 'El valor d''un determinant que té dues files iguals o proporcionals és:', '1', 'Diferent de zero.', 'Zero.', 'Depèn de la resta de files.', 'C', 'Aquesta és una de les propietats bàsiques dels determinants. Qualsevol matriu amb línies linealment dependents té determinant zero i, per tant, no té rang màxim.'),
('matematiques-ii', 'Àlgebra Lineal (Matrius i Sistemes)', 'Si resolem un sistema mitjançant la Regla de Cramer, el valor de la incògnita $x$ s''obté dividint:', 'El determinant d''A entre el determinant de la matriu associada a x.', 'El determinant d''A* entre el determinant d''A.', 'El determinant de la matriu obtinguda al substituir la columna de les $x$ pels termes independents, entre el determinant de la matriu de coeficients.', 'L''adjunt de $x$ entre $|A|$.', 'C', 'Aquesta és la definició exacta de la Regla de Cramer: $x_i = \frac{|A_i|}{|A|}$. Recorda que només es pot aplicar si el sistema és un SCD.'),
('matematiques-ii', 'Geometria a l''Espai', 'Quin és el vector normal (perpendicular) al pla d''equació general $\pi: 3x - 4y + 2z - 5 = 0$?', '$\vec{n} = (3, 4, 2)$', '$\vec{n} = (-3, -4, -2)$', '$\vec{n} = (3, -4, 2)$', '$\vec{n} = (0, 0, -5)$', 'C', 'En l''equació implícita del pla $Ax + By + Cz + D = 0$, els coeficients de $x, y, z$ $(A, B, C)$ coincideixen exactament amb les components del vector normal al pla.'),
('matematiques-ii', 'Geometria a l''Espai', 'Dos vectors $\vec{u}$ i $\vec{v}$ no nuls són perpendiculars (ortogonals) si i només si:', 'El seu producte vectorial és zero.', 'El seu producte escalar és u.', 'El seu producte escalar és zero ($\vec{u} \cdot \vec{v} = 0$).', 'Són paral·lels a l''eix Z.', 'C', 'El producte escalar és $\vec{u} \cdot \vec{v} = |\vec{u}| \cdot |\vec{v}| \cdot \cos(\alpha)$. Com que el cosinus de $90^\circ$ és zero, el producte escalar s''anul·la.'),
('matematiques-ii', 'Geometria a l''Espai', 'Com es pot trobar un vector que sigui simultàniament perpendicular a dos vectors diferents $\vec{u}$ i $\vec{v}$?', 'Fent el seu producte escalar.', 'Fent el seu producte vectorial ($\vec{u} \times \vec{v}$).', 'Sumant les seves components.', 'Fent el producte mixt.', 'B', 'Una propietat fonamental del producte vectorial és que dona com a resultat un vector que és ortogonal al pla format per $\vec{u}$ i $\vec{v}$. S''utilitza molt per trobar el vector normal d''un pla.'),
('matematiques-ii', 'Geometria a l''Espai', 'Quina condició s''ha de complir perquè tres vectors $\vec{u}$, $\vec{v}$ i $\vec{w}$ siguin coplanaris (estiguin en el mateix pla)?', 'Que la suma dels tres doni el vector nul.', 'Que el seu producte escalar sigui zero.', 'Que el seu determinant (o producte mixt) sigui diferent de zero.', 'Que el seu determinant (o producte mixt) sigui zero.', 'D', 'Si el determinant (producte mixt) de tres vectors és zero, significa que són linealment dependents i, per tant, no formen un volum. Es troben en el mateix pla.'),
('matematiques-ii', 'Geometria a l''Espai', 'Què representa geomètricament el mòdul del producte vectorial de dos vectors $|\vec{u} \times \vec{v}|$?', 'El volum del paral·lelepípede que formen.', 'L''àrea del paral·lelogram construït sobre aquests dos vectors.', 'La projecció de $\vec{u}$ sobre $\vec{v}$.', 'L''angle que formen.', 'B', 'El mòdul del producte vectorial coincideix amb l''àrea del paral·lelogram. Si dividim aquest resultat per 2, obtindrem l''àrea del triangle format pels dos vectors.'),
('matematiques-ii', 'Geometria a l''Espai', 'Si una recta $r$ té vector director $\vec{v}_r$ i un pla $\pi$ té vector normal $\vec{n}_\pi$, quan serà la recta PARAL·LELA al pla?', 'Quan $\vec{v}_r$ i $\vec{n}_\pi$ siguin paral·lels.', 'Quan el producte escalar $\vec{v}_r \cdot \vec{n}_\pi = 0$.', 'Quan el producte vectorial $\vec{v}_r \times \vec{n}_\pi = 0$.', 'No es pot saber amb aquests vectors.', 'B', 'És un raonament clàssic que crea confusió. Perquè la recta no talli el pla (sigui paral·lela), el seu vector director ha d''anar en la mateixa direcció que el pla. Per tant, $\vec{v}_r$ ha de ser perpendicular al vector normal del pla ($\vec{n}_\pi$).'),
('matematiques-ii', 'Geometria a l''Espai', 'L''equació contínua d''una recta que passa pel punt $P(p_1, p_2, p_3)$ i té vector director $\vec{v}=(v_1, v_2, v_3)$ és:', '$(x,y,z) = (p_1, p_2, p_3) + \lambda(v_1, v_2, v_3)$', '$\frac{x-v_1}{p_1} = \frac{y-v_2}{p_2} = \frac{z-v_3}{p_3}$', '$\frac{x-p_1}{v_1} = \frac{y-p_2}{v_2} = \frac{z-p_3}{v_3}$', '$Ax + By + Cz + D = 0$', 'C', 'Recorda: al numerador restem les coordenades del punt $P$, i al denominador col·loquem les components del vector director $\vec{v}$. L''opció A és l''equació vectorial.'),
('matematiques-ii', 'Geometria a l''Espai', 'Com calculem la distància d''un punt $P(x_0, y_0, z_0)$ a un pla $\pi: Ax + By + Cz + D = 0$?', 'Substituint el punt a l''equació del pla i dividint pel mòdul del vector normal $\sqrt{A^2+B^2+C^2}$.', 'Fent el producte vectorial entre el punt i el pla.', 'Trobant la distància entre l''origen i el pla.', 'Amb el producte mixt.', 'A', 'La fórmula directa és $d(P, \pi) = \frac{|Ax_0 + By_0 + Cz_0 + D|}{\sqrt{A^2 + B^2 + C^2}}$. Sempre amb valor absolut al numerador perquè és una distància.'),
('matematiques-ii', 'Geometria a l''Espai', 'Si volem comprovar si quatre punts $A, B, C, D$ són coplanaris, hem de:', 'Comprovar si el determinant dels vectors $\vec{AB}, \vec{AC}, \vec{AD}$ és zero.', 'Sumar les seves coordenades.', 'Fer el producte escalar de tots ells.', 'Totes són incorrectes.', 'A', 'Es fixarà un punt com a origen (per exemple A) i es construiran els tres vectors que van cap a la resta de punts. Si el determinant d''aquests 3 vectors és 0, els vectors són coplanaris i els punts també.'),
('matematiques-ii', 'Geometria a l''Espai', 'Si un pla $\pi_1$ i un pla $\pi_2$ tenen vectors normals paral·lels, la posició relativa entre ells és:', 'Es tallen perpendicularment en una recta.', 'Són paral·lels o coincidents.', 'Es creuen en un únic punt.', 'No tenen cap punt en comú mai.', 'B', 'Si els seus vectors normals apunten en la mateixa direcció, els plans no tenen inclinació l''un respecte de l''altre. Per saber si són coincidents o estrictament paral·lels s''ha de mirar el terme independent ($D$).'),
('matematiques-ii', 'Anàlisi (Funcions, Límits, Continuïtat i Derivades)', 'Segons el Teorema de Bolzano, si una funció $f(x)$ és contínua en un interval tancat $[a,b]$ i $f(a) \cdot f(b) < 0$, què podem garantir?', 'Que la funció és derivable en tot l''interval.', 'Que existeix almenys un punt $c \in (a,b)$ on $f(c) = 0$.', 'Que la funció té un màxim a l''interval.', 'Que $f(x)$ és constant a $[a,b]$.', 'B', 'És un teorema bàsic molt preguntat a la PBAU. Si la funció és contínua i passa d''un valor positiu a un de negatiu (o viceversa), obligatòriament ha de creuar l''eix X (ha de valer zero en algun punt intermedi).'),
('matematiques-ii', 'Anàlisi (Funcions, Límits, Continuïtat i Derivades)', 'Quina indeterminació es pot resoldre directament aplicant la Regla de L''Hôpital?', '$0 \cdot \infty$', '$1^\infty$', '$0 / 0$ i $\infty / \infty$', '$\infty - \infty$', 'C', 'L''Hôpital només es pot aplicar de manera directa en quocients amb indeterminació $0/0$ o $\infty/\infty$. Qualsevol altra indeterminació (com $0 \cdot \infty$) s''ha de transformar prèviament en un quocient.'),
('matematiques-ii', 'Anàlisi (Funcions, Límits, Continuïtat i Derivades)', 'Geomètricament, què representa el valor de la derivada d''una funció en un punt $x=a$ ($f''(a)$)?', 'L''àrea sota la corba en aquell punt.', 'El pendent de la recta tangent a la funció en el punt $x=a$.', 'L''equació de la recta normal en aquell punt.', 'El límit de la funció quan $x$ tendeix a $\infty$.', 'B', 'Aquesta és la interpretació geomètrica de la derivada. L''equació de la recta tangent en $x=a$ és $y - f(a) = f''(a) \cdot (x - a)$.'),
('matematiques-ii', 'Anàlisi (Funcions, Límits, Continuïtat i Derivades)', 'Una funció $f(x)$ presenta un MÀXIM relatiu en $x=c$ si:', '$f''(c) = 0$ i $f''''(c) > 0$.', '$f''(c) = 0$ i $f''''(c) < 0$.', '$f''''(c) = 0$.', 'El límit de la funció en $x=c$ no existeix.', 'B', 'La primera derivada igual a zero ens dóna els punts crítics (tangent horitzontal). La segona derivada ens indica la curvatura: si és negativa, la corba és còncava (forma de "M" invertida), indicant un màxim.'),
('matematiques-ii', 'Anàlisi (Funcions, Límits, Continuïtat i Derivades)', 'Es diu que una funció és contínua en $x=a$ si i només si:', '$\lim_{x \to a^-} f(x) = \lim_{x \to a^+} f(x) = f(a)$', 'Existeix $f(a)$ i és diferent de zero.', '$\lim_{x \to a} f(x) = \infty$', 'La funció és derivable en aquest punt.', 'A', 'Les tres condicions per la continuïtat són: els límits laterals han d''existir, han de ser iguals entre si, i aquest valor ha de coincidir amb el valor de la funció en el punt.'),
('matematiques-ii', 'Anàlisi (Funcions, Límits, Continuïtat i Derivades)', 'Si $\lim_{x \to \infty} f(x) = L$ (on $L$ és un nombre real finit), què podem afirmar sobre la gràfica de $f(x)$?', 'Té una asímptota vertical en $x=L$.', 'Té una asímptota obliqua.', 'Té una asímptota horitzontal a l''alçada $y=L$.', 'La funció no està acotada.', 'C', 'Quan $x$ es fa molt gran (o molt negativa), la funció s''estabilitza en un valor concret $L$. Aquesta és la definició d''una Asímptota Horitzontal.'),
('matematiques-ii', 'Anàlisi (Funcions, Límits, Continuïtat i Derivades)', 'La funció logaritme neperià $f(x) = \ln(x)$ té com a domini de definició:', 'Tot el conjunt dels nombres reals $\mathbb{R}$.', 'Els nombres reals més grans o iguals a zero $[0, \infty)$.', 'Estrictament els nombres reals positius $(0, \infty)$.', 'Els nombres reals diferents de zero $\mathbb{R} \setminus \{0\}$.', 'C', 'No existeix el logaritme de nombres negatius ni el logaritme de zero. L''argument del logaritme ha de ser estrictament major que 0.'),
('matematiques-ii', 'Anàlisi (Funcions, Límits, Continuïtat i Derivades)', 'Els punts d''inflexió d''una funció assenyalen:', 'On la funció passa de créixer a decréixer.', 'Un tall amb l''eix d''abscisses.', 'Un canvi en la curvatura (de còncava a convexa o viceversa).', 'On la funció no està definida.', 'C', 'Els punts d''inflexió es troben buscant els valors on la segona derivada és zero ($f''''(x) = 0$) i analitzant si hi ha un canvi de signe abans i després del punt.'),
('matematiques-ii', 'Anàlisi (Funcions, Límits, Continuïtat i Derivades)', 'La derivada de la funció composta $f(x) = e^{g(x)}$ aplicant la Regla de la Cadena és:', '$f''(x) = g(x) \cdot e^{g(x)-1}$', '$f''(x) = e^{g''(x)}$', '$f''(x) = g''(x) \cdot e^{g(x)}$', '$f''(x) = g''(x) \cdot e^x$', 'C', 'La derivada de l''exponencial d''una funció és la mateixa exponencial multiplicada per la derivada de l''exponent.'),
('matematiques-ii', 'Anàlisi (Funcions, Límits, Continuïtat i Derivades)', 'La relació entre continuïtat i derivabilitat en un punt és la següent:', 'Si és contínua, segur que és derivable.', 'Si és derivable, segur que és contínua.', 'Són conceptes totalment independents.', 'Totes les funcions definides a trossos no són ni contínues ni derivables.', 'B', 'La derivabilitat és una propietat "més exigent". Tota funció derivable en un punt és necessàriament contínua, però una funció pot ser contínua i no derivable (com en els "pics" o punts angulosos, tipus $f(x) = |x|$ en $x=0$).'),
('matematiques-ii', 'Anàlisi (Integrals, Àrees i Teoremes)', 'La Regla de Barrow per calcular la integral definida $\int_a^b f(x) \,dx$ estableix que el seu valor és:', '$F(b) \cdot F(a)$', '$F(a) - F(b)$', '$F(b) - F(a)$ (on $F(x)$ és una primitiva de $f(x)$).', 'La derivada de $f(x)$ avaluada en $b-a$.', 'C', 'La Regla de Barrow ens diu que avaluant la funció primitiva a l''extrem superior i restant-li el valor a l''extrem inferior obtenim la integral definida.'),
('matematiques-ii', 'Anàlisi (Integrals, Àrees i Teoremes)', 'Si es vol calcular l''àrea compresa entre l''eix d''abscisses ($y=0$) i la funció $f(x)$ a l''interval $[a,b]$, quin és el primer pas fonamental a l''examen de la PBAU?', 'Derivar $f(x)$ i igualar a 0.', 'Cercar els punts de tall de la funció amb l''eix d''abscisses resolent $f(x) = 0$.', 'Integrar directament entre $a$ i $b$.', 'Multiplicar per $-1$ tota l''expressió.', 'B', 'Si la funció talla l''eix d''abscisses dins de l''interval $[a,b]$, canviarà de signe i algunes àrees seran "negatives". S''ha de dividir la integral en trossos per agafar el valor absolut de cada part i sumar-les correctament.'),
('matematiques-ii', 'Anàlisi (Integrals, Àrees i Teoremes)', 'La fórmula d''integració per parts s''escriu com: $\int u \,dv =$', '$\int v \,du - u \cdot v$', '$u \cdot v + \int v \,du$', '$u \cdot v - \int v \,du$', '$d(u \cdot v)$', 'C', 'Coneguda memotècnicament com "Un Día Vi Una Vaca Menos Integrando Vestida De Uniforme".'),
('matematiques-ii', 'Anàlisi (Integrals, Àrees i Teoremes)', 'La primitiva principal de la funció $f(x) = \frac{1}{x}$ és:', '$\ln|x| + C$', '$e^x + C$', '$\frac{-1}{x^2} + C$', '$x^0 + C$', 'A', 'És l''excepció a la regla de la potència per integrar $x^n$. Quan $n=-1$, la integral genera un logaritme neperià. El valor absolut garanteix que estigui definit per a valors negatius.'),
('matematiques-ii', 'Anàlisi (Integrals, Àrees i Teoremes)', 'Segons el Teorema de Rolle, si $f(x)$ és contínua en $[a,b]$, derivable en $(a,b)$ i a més es compleix que $f(a) = f(b)$, aleshores:', 'Existeix un punt $c \in (a,b)$ on $f(c) = 0$.', 'Existeix un punt $c \in (a,b)$ on $f''(c) = 0$.', 'La funció no pot tenir punts d''inflexió.', 'La integral definida entre $a$ i $b$ és zero.', 'B', 'Com que la funció parteix d''una alçada i torna exactament a la mateixa alçada ($f(a)=f(b)$), per força ha d''haver "girat" (si no és constant), de manera que hi ha un punt on la recta tangent és horitzontal.'),
('matematiques-ii', 'Anàlisi (Integrals, Àrees i Teoremes)', 'Si $f(x)$ és una funció IMPARELLA (simetria respecte l''origen, $f(-x) = -f(x)$), quant val la integral definida $\int_{-a}^{a} f(x) \,dx$?', 'El doble de la integral entre 0 i $a$.', 'L''àrea total compresa amb l''eix X.', 'Zero.', '$a^2/2$', 'C', 'En una funció imparella (com $\sin(x)$ o $x^3$), l''àrea generada al costat negatiu de l''eix es cancel·la algebraicament amb l''àrea generada al costat positiu, donant un resultat net de 0.'),
('matematiques-ii', 'Anàlisi (Integrals, Àrees i Teoremes)', 'L''àrea de la regió del pla limitada per dues funcions $f(x)$ i $g(x)$ que es tallen en els punts $x=a$ i $x=b$ es calcula com:', '$\int_a^b |f(x) - g(x)| \,dx$', '$\int_a^b (f(x) \cdot g(x)) \,dx$', '$\int_a^b |f(x)| \,dx - \int_a^b |g(x)| \,dx$', '$f(b) - g(a)$', 'A', 'Sempre s''ha d''integrar la funció "sostre" menys la funció "terra". Si no sabem quina va per sobre, posar tota la diferència en valor absolut ens assegura un resultat d''àrea positiu.'),
('matematiques-ii', 'Anàlisi (Integrals, Àrees i Teoremes)', 'Quina tècnica d''integració recomana l''acrònim ALPES / ILATE per triar la funció ''$u$''?', 'Canvi de variable.', 'Integració per fraccions simples.', 'Integració per parts.', 'Aplicació de la Regla de Barrow.', 'C', 'Serveix per determinar la prioritat de substitució de $u$: (I)nverses trigonomètriques, (L)ogarítmiques, (A)lgebraiques, (T/P)rigonomètriques, (E)xponencials.'),
('matematiques-ii', 'Anàlisi (Integrals, Àrees i Teoremes)', 'En un problema d''optimització (per exemple minimitzar material d''un cilindre), un cop obtinguda la funció d''una variable, com garantim que el punt trobat és un mínim?', 'Si el límit quan $x \to \infty$ és zero.', 'Si la segona derivada avaluada en aquest punt és positiva ($f''''(c) > 0$).', 'Si la segona derivada avaluada en aquest punt és negativa ($f''''(c) < 0$).', 'Si talla l''eix X.', 'B', 'Trobar on $f''(x) = 0$ ens dona els punts crítics. Si al substituir-los a la segona derivada el resultat és positiu, es tracta d''un mínim (curvatura còncava en forma de "U").'),
('matematiques-ii', 'Anàlisi (Integrals, Àrees i Teoremes)', 'El Teorema Fonamental del Càlcul relaciona dues operacions matemàtiques que, essent de naturalesa diferent, resulten ser inverses. Quines són?', 'Suma i Producte.', 'Límits i Continuïtat.', 'Derivació i Integració.', 'Matrius i Determinants.', 'C', 'Ens diu que si derivem la funció integral $F(x) = \int_a^x f(t) \,dt$, obtindrem la mateixa funció original $f(x)$. Això permet fer servir la regla de Barrow de manera pràctica.'),
('matematiques-ii', 'Probabilitat', 'Segons l''axiomàtica bàsica, si dos successos $A$ i $B$ són incompatibles (mútuament excloents), es compleix que:', '$P(A \cap B) = P(A) \cdot P(B)$', '$P(A \cup B) = 1$', '$P(A \cap B) = 0$', '$P(A) = P(B)$', 'C', 'Incompatibles vol dir que no poden donar-se a la vegada. La seva intersecció és el conjunt buit i, per tant, la probabilitat que passin simultàniament és zero.'),
('matematiques-ii', 'Probabilitat', 'Dos successos $A$ i $B$ s''anomenen INDEPENDENTS si es compleix la igualtat:', '$P(A \cap B) = 0$', '$P(A \cap B) = P(A) \cdot P(B)$', '$P(A \cup B) = P(A) + P(B)$', '$P(A|B) = P(B|A)$', 'B', 'Aquesta és la regla fonamental per demostrar la independència en un problema de la UIB. Si conèixer $B$ no altera la probabilitat d''$A$, llavors $P(A \cap B)$ és simplement el producte de les dues probabilitats.'),
('matematiques-ii', 'Probabilitat', 'La fórmula de la probabilitat condicionada de l''esdeveniment $A$ sabent que ha ocorregut $B$ és $P(A|B) =$', '$\frac{P(A \cap B)}{P(A)}$', '$P(A) \cdot P(B)$', '$\frac{P(A \cap B)}{P(B)}$', '$\frac{P(A)}{P(B)}$', 'C', 'Limitem el nostre espai mostral al succés que JA SABEM que ha passat ($B$). Per això $P(B)$ va al denominador. Al numerador hi posem la part comuna on succeeixen tots dos ($A \cap B$).'),
('matematiques-ii', 'Probabilitat', 'Què prediuen les Lleis de De Morgan sobre la probabilitat del contrari de la unió: $P(\overline{A \cup B})$?', 'Que és igual a $P(\overline{A}) \cdot P(\overline{B})$.', 'Que és igual a $P(\overline{A} \cap \overline{B})$.', 'Que és igual a $P(\overline{A} \cup \overline{B})$.', 'Que és igual a $1$.', 'B', 'El complementari de la unió és la intersecció dels complementaris: "No succeeix ni $A$ ni $B$" equival a dir "No succeeix $A$ I, al mateix temps, No succeeix $B$".'),
('matematiques-ii', 'Probabilitat', 'Una urna té boles blanques i negres. Es treuen dues boles de l''urna *sense reposició*. La probabilitat de la segona extracció depèn del resultat de la primera. Com es pot modelar eficaçment?', 'És un experiment amb successos independents.', 'Cal utilitzar la distribució Normal.', 'És recomanable utilitzar un Diagrama d''Arbre i probabilitat condicionada.', 'Utilitzant exclusivament les lleis de De Morgan.', 'C', 'Quan hi ha experiments compostos (pas rere pas) on l''espai mostral va canviant per manca de reposició, el diagrama d''arbre reflecteix clarament com canvien les probabilitats (les branques són els condicionants).'),
('matematiques-ii', 'Probabilitat', 'L''expressió $P(A \cup B) = P(A) + P(B) - P(A \cap B)$ rep el nom de:', 'Teorema de Bayes.', 'Regla d''Addició per a qualsevol parell de successos.', 'Regla del Succés Contrari.', 'Probabilitat Total.', 'B', 'És fonamental restar la intersecció perquè, si sumem $P(A)$ i $P(B)$, estem comptant els casos on ocorren tots dos successos de manera duplicada.'),
('matematiques-ii', 'Probabilitat', 'Quin teorema utilitzem freqüentment en els problemes de diagrames d''arbre per recórrer les rames "cap enrere" i descobrir l''origen d''un resultat que ja s''ha produït (ex: sabem que una peça és defectuosa, quina és la probabilitat que provingui de la Màquina A)?', 'Teorema del Lògic de Boole.', 'Teorema de la Probabilitat Total.', 'Teorema de Bayes.', 'Teorema de Rouché-Frobenius.', 'C', 'El Teorema de Bayes calcula la probabilitat "a posteriori". Permet intercanviar el condicionant ($P(A_i|B)$ quan coneixem $P(B|A_i)$ i $P(A_i)$). El denominador sempre és la probabilitat total de $B$.'),
('matematiques-ii', 'Probabilitat', 'Quant suma sempre la probabilitat d''un succés i la del seu succés contrari: $P(A) + P(\overline{A})$?', 'Zero.', 'Depèn del problema.', 'Entre 0 i 1.', 'Exactament 1.', 'D', 'L''espai mostral sencer (tot el que pot ocórrer) té probabilitat $1$ (o $100\%$). Un esdeveniment o bé succeeix, o bé no succeeix; per tant formen un sistema complet d''esdeveniments.'),
('matematiques-ii', 'Probabilitat', 'Tenim l''esdeveniment "Aprovar Matemàtiques" i l''esdeveniment "Ser d''una altra Galàxia". Si aquests dos esdeveniments són totalment independents, quant val $P(\text{Aprovar} | \text{Galàxia})$?', 'Zero.', '$P(\text{Galàxia})$.', '$P(\text{Aprovar})$.', 'Un valor negatiu.', 'C', 'Si dos esdeveniments són independents, saber que ha ocorregut un no aporta absolutament cap informació nova sobre l''altre. Per tant, la probabilitat condicionada es redueix a la probabilitat original: $P(A|B) = P(A)$.'),
('matematiques-ii', 'Probabilitat', 'Per calcular la probabilitat d''una diferència de successos (que passi $A$ però NO passi $B$), quina expressió s''utilitza?', '$P(A - B) = P(A) - P(B)$', '$P(A \cap \overline{B}) = P(A) - P(A \cap B)$', '$P(A \cup B) = P(A) / P(B)$', '$P(A - B) = P(\overline{A}) \cdot P(B)$', 'B', 'A la probabilitat total que passi $A$, només li has de treure la "porció" on $A$ i $B$ es superposen (la intersecció), així et quedarà només la part on $A$ succeeix exclusivament sense interferència de $B$.'),
('macs-ii', 'Probabilitat', 'Si A i B són dos successos INCOMPATIBLES (que no poden ocórrer alhora), quant val la probabilitat de la seva unió $P(A \cup B)$?', '$P(A) \cdot P(B)$', '$P(A) + P(B) - P(A \cap B)$', '$P(A) + P(B)$', 'Zero.', 'C', 'Com que són incompatibles, la seva intersecció és buida ($P(A \cap B) = 0$). Per tant, la fórmula general de la unió es simplifica a la suma directa de les probabilitats.'),
('macs-ii', 'Probabilitat', 'La probabilitat que un client compri un producte A és 0.4. La probabilitat que compri el producte B és 0.3. Si sabem que la compra de B és INDEPENDENT de la compra d''A, quina és la probabilitat que compri tots dos productes?', '0.7', '0.12', '0.1', 'No es pot calcular.', 'B', 'Si dos successos són independents, la probabilitat de la seva intersecció és el producte de les seves probabilitats: $P(A \cap B) = P(A) \cdot P(B) = 0.4 \cdot 0.3 = 0.12$.'),
('macs-ii', 'Probabilitat', 'En un diagrama d''arbre, la suma de les probabilitats de les branques que surten d''un mateix nus ha de ser sempre:', 'Menor que 1.', 'Exactament 1.', 'Depèn del nombre de branques.', '0.5', 'B', 'Les branques que surten d''un nus representen totes les opcions possibles (un sistema complet de successos). Per tant, la suma de les seves probabilitats ha de ser sempre el 100% (és a dir, 1).'),
('macs-ii', 'Probabilitat', 'El Teorema de Bayes s''utilitza principalment per a calcular:', 'La probabilitat total d''un succés al final d''un experiment.', 'La unió de tres o més successos.', 'Probabilitats "a posteriori" (sabent el resultat final, quina era la probabilitat del camí d''origen).', 'L''esperança matemàtica d''un joc.', 'C', 'Bayes s''utilitza quan ja coneixem el resultat (ex: "sabem que la peça és defectuosa") i volem "tornar enrere" a l''arbre per saber quina màquina l''ha produïda: $P(A|B) = P(A \cap B) / P(B)$.'),
('macs-ii', 'Probabilitat', 'D''una baralla de cartes s''extreuen dues cartes CONSECUTIVAMENT I SENSE REPOSICIÓ. Què podem afirmar dels successos?', 'Són successos independents.', 'Són successos dependents.', 'Són successos incompatibles.', 'La probabilitat de la segona extracció no canvia.', 'B', 'Al no tornar la primera carta a la baralla, l''espai mostral canvia (hi ha una carta menys). Per tant, el resultat de la primera extracció condiciona directament la probabilitat de la segona. Són dependents.'),
('macs-ii', 'Probabilitat', 'Les Lleis de De Morgan afirmen que la probabilitat del contrari de la unió $P(\overline{A \cup B})$ és igual a:', '$P(\overline{A}) \cup P(\overline{B})$', '$1 - P(A \cap B)$', '$P(\overline{A} \cap \overline{B})$', '$P(\overline{A}) + P(\overline{B})$', 'C', 'El complementari de la unió és la intersecció dels complementaris. "No passa ni A ni B" és el mateix que "No passa A, i alhora, no passa B".'),
('macs-ii', 'Probabilitat', 'Si $P(A) = 0.6$, quant val la probabilitat del seu succés contrari o complementari $P(\overline{A})$?', '0.6', '0.4', '-0.6', '0', 'B', 'La probabilitat d''un succés i la del seu contrari sumen sempre 1. Llavors, $P(\overline{A}) = 1 - P(A) = 1 - 0.6 = 0.4$.'),
('macs-ii', 'Probabilitat', 'A la fórmula de la probabilitat condicionada $P(A|B) = \frac{P(A \cap B)}{P(B)}$, el denominador $P(B)$ representa:', 'El nou espai mostral reduït al succés que sabem que ja ha passat.', 'La probabilitat que passin A i B alhora.', 'L''error de l''experiment.', 'El succés menys probable.', 'A', 'Quan condicionem a B, estem descartant tots els casos on B no passa. El nostre "nou total" d''opcions (el denominador) passa a ser exclusivament la probabilitat de B.'),
('macs-ii', 'Probabilitat', 'Per calcular la probabilitat que passi el succés A PERÒ NO passi el succés B ($A - B$), utilitzem la fórmula:', '$P(A) - P(B)$', '$P(A) / P(B)$', '$P(A) - P(A \cap B)$', '$P(A) \cdot P(\overline{B})$', 'C', 'A la probabilitat total del cercle A li hem de restar el "tros" que comparteix amb B (la intersecció), per quedar-nos només amb la part exclusiva d''A.'),
('macs-ii', 'Probabilitat', 'Si en un problema ens diuen: "el 20% dels treballadors són directius, i d''aquests, el 40% són dones", quina operació farem per trobar la probabilitat de ser "Directiu I Dona"?', 'Sumar $0.20 + 0.40$', 'Multiplicar $0.20 \cdot 0.40$', 'Dividir $0.40 / 0.20$', 'Aplicar la Llei de Laplace.', 'B', 'Aquest és el típic camí d''un diagrama d''arbre. Estem calculant la intersecció de successos dependents: $P(\text{Directiu} \cap \text{Dona}) = P(\text{Directiu}) \cdot P(\text{Dona}|\text{Directiu})$.'),
('macs-ii', 'Estadística Inferencial (Distribució Normal i Intervals)', 'En una Distribució Normal Estàndard $N(0, 1)$, què representa la taula de probabilitats que ens donen a l''examen?', 'La probabilitat que $Z$ sigui exactament igual a un valor $z$.', 'La probabilitat que $Z$ sigui més gran o igual que $z$ ($P(Z \ge z)$).', 'L''àrea sota la campana de Gauss a l''esquerra del valor $z$ ($P(Z \le z)$).', 'La mitjana de la mostra.', 'C', 'La taula de la normal acumula la probabilitat des de $-\infty$ fins a un valor $z$ positiu. Dona sempre l''àrea que queda a l''esquerra de la corba.'),
('macs-ii', 'Estadística Inferencial (Distribució Normal i Intervals)', 'Tenim una variable aleatòria $X$ que segueix una distribució Normal $N(\mu=50, \sigma=10)$. Com la "tipifiquem" per poder usar la taula de la Normal $Z(0,1)$?', '$Z = (X - 10) / 50$', '$Z = (X - 50) / 10$', '$Z = X \cdot 50 / 10$', 'No cal tipificar, la taula serveix per a qualsevol Normal.', 'B', 'La fórmula de tipificació és $Z = \frac{X - \mu}{\sigma}$. Es resta la mitjana poblacional i es divideix per la desviació típica.'),
('macs-ii', 'Estadística Inferencial (Distribució Normal i Intervals)', 'Si la mitjana de les notes d''una mostra d''alumnes és 6,5, on estarà situat el centre de l''Interval de Confiança per a la mitjana de tota la població?', 'A 0.', 'Exactament a 6,5.', 'Depèn del nivell de confiança.', 'Depèn de la grandària de la mostra.', 'B', 'L''interval de confiança es construeix sempre de forma simètrica sumant i restant l''Error Màxim al voltant de la mitjana de la mostra ($\bar{x}$). El centre sempre és $\bar{x}$.'),
('macs-ii', 'Estadística Inferencial (Distribució Normal i Intervals)', 'Si AUGMENTEM la mida de la mostra ($n$) d''un estudi estadístic mantenint el mateix nivell de confiança, què li passa a l''amplitud de l''Interval de Confiança?', 'Augmenta (és més ample).', 'Disminueix (és més estret i precís).', 'Es manté igual.', 'L''error màxim es duplica.', 'B', 'L''Error Màxim és $E = z_{\alpha/2} \cdot \frac{\sigma}{\sqrt{n}}$. Com que $n$ està al denominador, si $n$ creix, l''error disminueix, fent que l''interval sigui més estret i tinguem més precisió.'),
('macs-ii', 'Estadística Inferencial (Distribució Normal i Intervals)', 'Volem un nivell de confiança del 95% ($1 - \alpha = 0.95$). Quin valor de $z_{\alpha/2}$ buscarem a la taula per posar a la fórmula de l''error?', 'El valor de z que deixa per sota una àrea de 0.95.', 'El valor de z que deixa per sota una àrea de 0.975.', 'El valor de z que deixa per sota una àrea de 0.05.', '1.645', 'B', 'Si la confiança és 0.95, sobra un $\alpha = 0.05$. Com que la corba té dues cues, dividim $\alpha/2 = 0.025$. A la taula hem de buscar l''àrea $0.95 + 0.025 = 0.975$, que correspon a $z = 1.96$.'),
('macs-ii', 'Estadística Inferencial (Distribució Normal i Intervals)', 'Si volem trobar la probabilitat que una variable Normal $Z$ sigui MAJOR que 1.5 ($P(Z > 1.5)$), com ho calculem amb la taula?', 'Mirem directament el valor 1.5 a la taula.', 'Mirem el valor de -1.5 a la taula.', 'Fem $1 - P(Z \le 1.5)$ (on $P(Z \le 1.5)$ és el valor de la taula).', 'És directament 0.', 'C', 'Com que l''àrea total sota la campana és 1, i la taula només ens dóna probabilitats "menors que" (cap a l''esquerra), per trobar l''àrea de la dreta hem de restar l''àrea esquerra a 1.'),
('macs-ii', 'Estadística Inferencial (Distribució Normal i Intervals)', 'Per a qualsevol variable aleatòria contínua (com la Distribució Normal), quina és la probabilitat que prengui un valor EXACTE (ex: $P(X = 25)$)?', '0.5', '1', 'Depèn de la mitjana.', 'Zero.', 'D', 'En una distribució contínua, hi ha infinits valors possibles. L''àrea sota la corba per a un sol punt (sense amplada) és nul·la. Per això $P(X = a) = 0$ i sempre calculem probabilitats en intervals ($P(X \le a)$).'),
('macs-ii', 'Estadística Inferencial (Distribució Normal i Intervals)', 'La fórmula per calcular la mida MÍNIMA de la mostra ($n$) necessària per no superar un error $E$ determinat és:', '$n = (z_{\alpha/2} \cdot \sigma) / E$', '$n = \left(\frac{z_{\alpha/2} \cdot \sigma}{E}\right)^2$', '$n = z_{\alpha/2} \cdot E / \sigma$', '$n = E^2 / \sigma$', 'B', 'Aquesta fórmula surt d''aïllar la $n$ de la fórmula de l''Error Màxim $E = z_{\alpha/2} \cdot \frac{\sigma}{\sqrt{n}}$. Cal recordar que el resultat s''ha d''arrodonir SEMPRE cap a l''enter superior.'),
('macs-ii', 'Estadística Inferencial (Distribució Normal i Intervals)', 'En un interval de confiança, la diferència entre el límit superior de l''interval i el límit inferior equival a:', 'L''error màxim admès ($E$).', 'La mitjana de la mostra ($\bar{x}$).', 'El doble de l''error màxim ($2E$).', 'La desviació típica poblacional ($\sigma$).', 'C', 'Com que l''interval és $(\bar{x} - E, \bar{x} + E)$, l''amplada total de l''interval (límit superior menys límit inferior) mesura exactament dues vegades l''error ($2E$).'),
('macs-ii', 'Estadística Inferencial (Distribució Normal i Intervals)', 'Com es resol la probabilitat d''un nombre negatiu a la taula Normal $P(Z \le -a)$ on $a > 0$?', 'La taula ja inclou nombres negatius.', 'És igual a $P(Z \ge a)$, que es calcula fent $1 - P(Z \le a)$.', 'És zero.', 'Es multiplica el valor de la taula per -1.', 'B', 'Per la simetria geomètrica de la Campana de Gauss respecte a l''eix Y, l''àrea a l''esquerra d''un valor negatiu (la cua esquerra) és exactament igual a l''àrea a la dreta d''aquest mateix valor en positiu (la cua dreta).'),
('macs-ii', 'Àlgebra (Matrius i Sistemes d''Equacions)', 'Per poder multiplicar dues matrius, $A \cdot B$, quina condició geomètrica de dimensions s''ha de complir estrictament?', 'Han de tenir les mateixes dimensions exactes.', 'El nombre de columnes d''A ha de ser igual al nombre de files de B.', 'Ambdues han de ser matrius quadrades.', 'El nombre de files d''A ha de ser igual al nombre de columnes de B.', 'B', 'Aquesta és la regla fonamental del producte de matrius. Si A és d''ordre $(m \times n)$ i B és d''ordre $(p \times q)$, el producte només és possible si $n = p$. La matriu resultant tindrà dimensió $(m \times q)$.'),
('macs-ii', 'Àlgebra (Matrius i Sistemes d''Equacions)', 'Tenim un sistema d''equacions lineals que representa les vendes de tres tipus de productes a una empresa. Si resolem el sistema i trobem que és un "Sistema Incompatible", què significa econòmicament?', 'Que hi ha infinites solucions de preus per als productes.', 'Que hi ha un error en les dades i els requeriments es contradiuen (no hi ha cap solució possible).', 'Que tots els productes tenen preu zero.', 'Que hem de fer servir la matriu inversa.', 'B', 'Un sistema incompatible (SI) significa matemàticament que les equacions no es poden satisfer simultàniament. En un problema real, vol dir que les dades proporcionades (les vendes i els ingressos) són incongruents.'),
('macs-ii', 'Àlgebra (Matrius i Sistemes d''Equacions)', 'Volem resoldre l''equació matricial $A \cdot X + B = C$, sabent que $A$ és invertible. Quina és la passa correcta per aïllar $X$?', '$X = (C - B) / A$', '$X = A^{-1} \cdot (C - B)$', '$X = (C - B) \cdot A^{-1}$', '$X = A \cdot (C - B)^{-1}$', 'B', 'Primer passem B restant: $A \cdot X = C - B$. Per treure la A (que multiplica per l''esquerra), hem de multiplicar per $A^{-1}$ OBLIGATÒRIAMENT per l''esquerra a l''altre costat de la igualtat.'),
('macs-ii', 'Àlgebra (Matrius i Sistemes d''Equacions)', 'Segons el teorema de Rouché-Frobenius, un sistema té infinites solucions (Sistema Compatible Indeterminat) quan:', '$\text{Rang}(A) \neq \text{Rang}(A^*)$', '$\text{Rang}(A) = \text{Rang}(A^*) = \text{nombre d''incògnites}$', 'El determinant d''A és diferent de zero.', '$\text{Rang}(A) = \text{Rang}(A^*) < \text{nombre d''incògnites}$', 'D', 'Com que el rang és menor que el nombre d''incògnites, vol dir que ens sobren variables que actuen com a "paràmetres lliures", generant infinites combinacions que solucionen el sistema.'),
('macs-ii', 'Àlgebra (Matrius i Sistemes d''Equacions)', 'Una matriu quadrada NO té matriu inversa (és singular) quan:', 'Tots els elements són positius.', 'El seu determinant és igual a zero ($|A| = 0$).', 'El seu determinant és diferent de zero ($|A| \neq 0$).', 'És una matriu identitat.', 'B', 'A la fórmula de la matriu inversa ($A^{-1} = \frac{1}{|A|} \text{Adj}(A)^T$), dividim pel determinant. Si el determinant és zero, l''operació matemàtica no existeix.'),
('macs-ii', 'Àlgebra (Matrius i Sistemes d''Equacions)', 'La matriu Identitat $I$ compleix una propietat fonamental en la multiplicació de matrius. Quina?', 'Que converteix qualsevol matriu en la matriu nul·la.', '$A \cdot I = I \cdot A = A$ per a qualsevol matriu A compatible.', '$A \cdot I = A^{-1}$', 'No es pot multiplicar per altres matrius.', 'B', 'La matriu identitat actua exactament com el número "1" en l''àlgebra de nombres reals. És l''element neutre de la multiplicació.'),
('macs-ii', 'Àlgebra (Matrius i Sistemes d''Equacions)', 'Si transpusem una matriu (canviem files per columnes), què passa amb el seu determinant?', 'Canvia de signe.', 'Es torna zero.', 'El determinant no canvia ($|A| = |A^T|$).', 'S''inverteix ($1 / |A|$).', 'C', 'Aquesta és una propietat fonamental. Un determinant es pot desenvolupar per files o per columnes obtenint exactament el mateix valor. Per tant, la matriu i la seva transposada tenen el mateix determinant.'),
('macs-ii', 'Àlgebra (Matrius i Sistemes d''Equacions)', 'Tenim una empresa que fabrica dos tipus de mobles amb tres tipus de fusta. Si volem construir una matriu per resoldre els preus dels materials, quin mètode és el més directe si el sistema resulta ser quadrat i compatible determinat?', 'Derivació.', 'Regla de Cramer.', 'Teorema de Bayes.', 'Llei de Laplace.', 'B', 'La Regla de Cramer ($x = |A_x| / |A|$) és el mètode més eficaç i pautat per resoldre sistemes quadrats amb una única solució (SCD) de manera directa mitjançant determinants.'),
('macs-ii', 'Àlgebra (Matrius i Sistemes d''Equacions)', 'A la matriu ampliada ($A^*$) d''un sistema d''equacions d''economia, què col·loquem a la darrera columna?', 'Els coeficients de la x.', 'Els termes independents (les quantitats totals com pressupostos o totals de vendes).', 'Zeros sempre.', 'La matriu inversa.', 'B', 'La matriu ampliada s''escriu afegint una columna extra a la matriu de coeficients. Aquesta columna conté les constants que estan a la dreta del signe "=" en les equacions lineals.'),
('macs-ii', 'Àlgebra (Matrius i Sistemes d''Equacions)', 'Si s''intercanvien dues files en una matriu $3 \times 3$, el seu determinant:', 'Es manté igual.', 'Es fa zero.', 'Canvia de signe.', 'Es multiplica per 2.', 'C', 'Per les propietats dels determinants, cada vegada que s''intercanvien dues línies paral·leles (siguin files o columnes), el valor del determinant es multiplica per -1.'),
('macs-ii', 'Anàlisi (Funcions, Límits i Derivades)', 'En economia, si tenim una funció que modelitza els Ingressos $I(x)$ i una altra que modelitza els Costos $C(x)$ per produir $x$ unitats, com obtenim la funció de Beneficis $B(x)$?', '$B(x) = I(x) + C(x)$', '$B(x) = I(x) \cdot C(x)$', '$B(x) = I(x) / C(x)$', '$B(x) = I(x) - C(x)$', 'D', 'El benefici econòmic és la diferència entre tots els doblers que entren a la caixa (Ingressos) menys tots els doblers que costa fabricar el producte (Costos).'),
('macs-ii', 'Anàlisi (Funcions, Límits i Derivades)', 'Volem MAXIMITZAR els beneficis d''una empresa. Des del punt de vista matemàtic, quin és el primer pas que hem de fer amb la funció de beneficis $B(x)$?', 'Igualar-la a zero ($B(x) = 0$).', 'Calcular la seva derivada primera i igualar-la a zero ($B''(x) = 0$).', 'Calcular la seva integral.', 'Cercar una asímptota horitzontal.', 'B', 'L''optimització de funcions passa sempre per trobar els punts crítics (on el pendent de la recta tangent és zero). Això s''aconsegueix resolent $B''(x) = 0$.'),
('macs-ii', 'Anàlisi (Funcions, Límits i Derivades)', 'Un cop hem trobat el nombre d''unitats $x$ que fa que $B''(x) = 0$, com assegurem matemàticament que aquest punt és un MÀXIM de beneficis i no un mínim?', 'Comprovant que $B''''(x) < 0$ (Segona derivada negativa).', 'Comprovant que $B''''(x) > 0$ (Segona derivada positiva).', 'Substituint a la funció original i veient si dona positiu.', 'Fent un límit cap a l''infinit.', 'A', 'Si la segona derivada és negativa al punt crític, la funció té forma convexa o de "M" (corbada cap avall), cosa que confirma que ens trobem al cim de la muntanya (un màxim).'),
('macs-ii', 'Anàlisi (Funcions, Límits i Derivades)', 'Una funció definida a trossos representa el cost de la llum segons l''hora. Per comprovar si la funció no té salts bruscs de preu (és CONTÍNUA) en el moment de canvi de tram (ex: $x=12$), què s''ha de complir?', 'Que la derivada en $x=12$ valgui 0.', 'Que el límit de la funció per l''esquerra de 12 sigui igual al límit per la dreta de 12 i igual a $f(12)$.', 'Que el límit quan x tendeix a infinit sigui 12.', 'Que la funció sigui sempre positiva.', 'B', 'Aquesta és la condició ineludible de continuïtat en un punt: $\lim_{x \to 12^-} f(x) = \lim_{x \to 12^+} f(x) = f(12)$. Els dos trossos s''han de "connectar" exactament a la mateixa altura.'),
('macs-ii', 'Anàlisi (Funcions, Límits i Derivades)', 'El concepte econòmic de "Cost Marginal" es tradueix matemàticament com:', 'L''asímptota vertical de la funció de cost.', 'L''arrel quadrada de la funció de cost.', 'La derivada de la funció de cost total $C''(x)$.', 'La funció de cost dividida per $x$.', 'C', 'En economia, qualsevol magnitud "marginal" equival a la derivada de la magnitud total respecte de la quantitat produïda $x$. Indica l''increment de cost per produir una unitat addicional.'),
('macs-ii', 'Anàlisi (Funcions, Límits i Derivades)', 'Volem predir cap on tendeix el deute d''un país a llarg termini si apliquem el model matemàtic $f(t) = \frac{3t + 5}{t + 2}$ on $t$ són els anys. Què estem cercant?', 'Una asímptota vertical calculant $\lim_{t \to -2} f(t)$.', 'Una asímptota horitzontal calculant $\lim_{t \to \infty} f(t)$.', 'El mínim de la funció fent $f''(t) = 0$.', 'Una asímptota obliqua.', 'B', 'El comportament a "llarg termini" vol dir quan el temps s''escapa cap a l''infinit. Calcular el límit a l''infinit d''aquesta funció racional ens donarà 3, la seva asímptota horitzontal.'),
('macs-ii', 'Anàlisi (Funcions, Límits i Derivades)', 'El domini d''una funció polinòmica de grau 3 (tipus $f(x) = 2x^3 - 5x^2 + x - 1$) és:', 'Només els nombres positius.', 'Tots els nombres reals $\mathbb{R}$.', 'Tots els reals excepte on s''anul·la el denominador.', '$(-1, 1)$', 'B', 'Les funcions polinòmiques, molt usades en l''ajust de models econòmics simples, no tenen denominadors ni arrels, per la qual cosa mai presenten discontinuïtats i el seu domini sempre és $\mathbb{R}$.'),
('macs-ii', 'Anàlisi (Funcions, Límits i Derivades)', 'La derivada de la funció constant $f(x) = 5000$ (que representa un cost fix de lloguer que no depèn del volum de producció) val:', '5000', '$5000x$', 'Zero.', '$1/5000$', 'C', 'La derivada mesura la taxa de canvi. Com que el cost fix no canvia mai, independentment de les unitats que fabriquem, la seva taxa de canvi és 0.'),
('macs-ii', 'Anàlisi (Funcions, Límits i Derivades)', 'Què ens indica un punt d''inflexió en la gràfica d''evolució de l''atur d''un país al llarg dels mesos?', 'El mes on l''atur és més alt (màxim).', 'El mes on l''atur comença a decréixer si abans creixia.', 'El punt on canvia la curvatura (potser l''atur segueix pujant, però ho comença a fer més lentament).', 'El mes on l''atur és zero.', 'C', 'El punt d''inflexió (on $f''''(x) = 0$) marca el canvi de concavitat a convexitat (o a l''inrevés). En una crisi, significa que les coses segueixen empitjorant (creix), però el ritme d''empitjorament s''està frenant (passa de créixer ràpid a créixer lent).'),
('macs-ii', 'Anàlisi (Funcions, Límits i Derivades)', 'Si la derivada primera d''una funció de beneficis $B''(x)$ és NEGATIVA a l''interval $(100, 200)$, què vol dir?', 'Que la funció de beneficis és decreixent en aquest interval (fabriquem més però guanyem menys).', 'Que estem tenint pèrdues (benefici negatiu).', 'Que la funció és còncava.', 'Que hem trobat un mínim.', 'A', 'El signe de la derivada ens indica exclusivament la direcció de la funció. Derivada negativa = funció decreixent. (Atenció: guanyar menys no vol dir tenir pèrdues, només que el benefici va de baixada).'),
('macs-ii', 'Anàlisi (Integrals i Àrees)', 'Volem trobar la funció d''Ingressos totals $I(x)$ a partir de la funció d''Ingressos Marginals $I''(x)$. Quina operació matemàtica hem de realitzar?', 'Calcular l''asímptota obliqua.', 'Derivar $I''(x)$ una segona vegada.', 'Integrar la funció marginal $\int I''(x) dx$.', 'Multiplicar per $x$.', 'C', 'El Teorema Fonamental del Càlcul ens diu que la integració és l''operació inversa a la derivació. Per recuperar una funció "total" a partir d''una funció "marginal", hem d''integrar.'),
('macs-ii', 'Anàlisi (Integrals i Àrees)', 'La Regla de Barrow serveix per calcular la integral definida d''una funció $f(x)$ entre $a$ i $b$. La seva fórmula és:', '$\int_a^b f(x) dx = F(a) - F(b)$', '$\int_a^b f(x) dx = F(b) - F(a)$ on $F(x)$ és la primitiva de $f(x)$.', '$\int_a^b f(x) dx = f''(b) - f''(a)$', 'S''obté derivant els extrems.', 'B', 'Un cop calculada la primitiva $F(x)$ (la funció integrada), avaluem aquesta funció a l''extrem superior de l''interval i li restem el resultat d''avaluar-la a l''extrem inferior.'),
('macs-ii', 'Anàlisi (Integrals i Àrees)', 'Si la funció de beneficis d''una empresa $f(x)$ és sempre negativa entre l''any $x=2$ i l''any $x=5$, en calcular la integral definida $\int_2^5 f(x) dx$, quin resultat obtindrem?', 'Un valor positiu que representa l''àrea geomètrica.', 'Zero.', 'Un valor negatiu.', 'No es pot calcular la integral d''una funció negativa.', 'C', 'La integral definida (sense posar valors absoluts) retorna el valor algebraic pur. Si la funció està per sota de l''eix X, l''àrea comptarà en negatiu, indicant una pèrdua acumulada de beneficis.'),
('macs-ii', 'Anàlisi (Integrals i Àrees)', 'Si volem calcular L''ÀREA geomètrica compresa entre la funció $f(x) = x^2 - 4$ i l''eix OX ($y=0$), abans d''integrar OBLIGATÒRIAMENT hem de:', 'Trobar on la segona derivada val 0.', 'Calcular els punts de tall amb l''eix OX resolent $f(x) = 0$.', 'Fer la inversa de la funció.', 'Derivar la funció per veure on creix.', 'B', 'Per calcular àrees de manera correcta, hem de veure en quins punts la funció creua l''eix d''abscisses, ja que si una part de l''àrea cau per sota de l''eix i una altra per sobre, sense dividir l''interval s''anul·larien erròniament.'),
('macs-ii', 'Anàlisi (Integrals i Àrees)', 'Quant val la integral indefinida més senzilla d''un polinomi simple: $\int x^3 dx$?', '$3x^2 + C$', '$\frac{x^4}{4} + C$', '$\frac{x^3}{3} + C$', '$x^4 + C$', 'B', 'La regla bàsica d''integració de potències és: sumar 1 a l''exponent i dividir pel nou exponent resultant. Això s''aplica per a qualsevol potència excepte per a l''exponent -1.'),
('macs-ii', 'Anàlisi (Integrals i Àrees)', 'Quina és la raó matemàtica per incloure la lletra $+ C$ (la constant d''integració) en resoldre una integral indefinida?', 'Perquè totes les funcions inclouen lletres.', 'Perquè la derivada de qualsevol constant és 0, així que hi ha infinites funcions primitives que difereixen només en una constant.', 'Per calcular la mitjana de l''àrea.', 'Perquè a MACS II s''acostuma a posar per formalisme, però no significa res.', 'B', 'Si derives $F(x) = x^2 + 5$ dóna $2x$. Si derives $F(x) = x^2 - 100$ també dóna $2x$. Per tant, l''antiderivada de $2x$ inclou totes aquestes infinites possibilitats marcades pel terme genèric $+ C$.'),
('macs-ii', 'Anàlisi (Integrals i Àrees)', 'Volem calcular l''àrea compresa entre les corbes de Costos $C(x)$ i Ingressos $I(x)$ entre $x=10$ i $x=50$. L''expressió de l''integral serà:', '$\int_{10}^{50} (I(x) + C(x)) dx$', '$\int_{10}^{50} \frac{I(x)}{C(x)} dx$', '$\int_{10}^{50} |I(x) - C(x)| dx$', '$\int_{10}^{50} C''(x) dx$', 'C', 'Per calcular l''àrea entre dues corbes, cal fer la integral de la seva resta (funció superior menys inferior). Per assegurar un valor positiu d''àrea sense haver de dibuixar-les per veure quina va per sobre, es pren el valor absolut de la diferència.'),
('macs-ii', 'Anàlisi (Integrals i Àrees)', 'L''àrea del recinte limitat per la funció de densitat d''una distribució de probabilitat (com la Normal) i l''eix d''abscisses sempre val:', '$0.5$', 'Depèn de la mitjana.', 'Infinit.', 'Exactament $1$.', 'D', 'En estadística, l''àrea total sota la corba d''una funció de densitat representa el 100% de les probabilitats de l''espai mostral. En valor numèric, aquest 100% equival a una àrea matemàtica d''1.'),
('macs-ii', 'Anàlisi (Integrals i Àrees)', 'A quina funció pròpia de MACS II dóna lloc la integral $\int \frac{1}{x} dx$?', '$x^0 + C$', '$e^x + C$', '$\ln|x| + C$', '$-\frac{1}{x^2} + C$', 'C', 'Com dèiem, és l''única excepció de la regla de les potències (ja que donaria divisió per 0). L''antiderivada de $x^{-1}$ (o $1/x$) és la funció logaritme neperià en valor absolut.'),
('macs-ii', 'Anàlisi (Integrals i Àrees)', 'Si derivem una funció de costos $C(x)$ per trobar el cost marginal, i tot seguit, integrem aquest resultat, què obtenim finalment?', 'L''asímptota del cost.', 'Els beneficis.', 'La funció de costos original, $C(x)$, excepte per un terme constant perdut en la derivació.', 'Zero.', 'C', 'En encadenar una derivada amb una integral s''anul·la l''efecte operatiu (com elevar al quadrat i després fer l''arrel). Tot i això, al derivar s''esborren els costos fixos (les constants numèriques soltes), i al reintegrar, aquests costos fixos queden emmascarats sota la "$C$" de la constant d''integració.');
